WITH valid AS (SELECT *, GREATEST(unit_price, quantity) greatest_unit_price_quantity FROM order_items WHERE unit_price > 310) SELECT CASE WHEN greatest_unit_price_quantity >= 85 THEN 'HIGH' ELSE 'LOW' END AS greatest_unit_price_quantity_tier, order_id, APPROX_PERCENTILE(unit_price, 0.9) AS unit_price_p90, BIT_OR(quantity) AS quantity_bit_or, COUNT(DISTINCT product_id) AS distinct_product_ids, BIT_AND(quantity) AS quantity_bit_and, COUNT(DISTINCT order_id) AS distinct_order_ids, ROUND(AVG(unit_price), 2) AS avg_unit_price FROM valid GROUP BY ROLLUP (CASE WHEN greatest_unit_price_quantity >= 85 THEN 'HIGH' ELSE 'LOW' END, order_id)
